[
  {
    "statement": "Several factors influence the success of chemical control for invasive aquatic plants like water primrose and parrot's feather.",
    "citations": []
  },
  {
    "statement": "For water primrose, the herbicide triclopyr TEA applied at a 0.25% concentration has been found to kill 100% of young plants.",
    "citations": [
      "1139"
    ]
  },
  {
